(function(){const music=document.getElementById("bgMusic");const btn=document.getElementById("soundBtn");if(!music||!btn)return;let hasStarted=false;let isFinished=false;function setPlaying(){btn.classList.remove("paused");btn.classList.add("playing")}function setPaused(){btn.classList.remove("playing");btn.classList.add("paused")}function tryPlay(){if(hasStarted)return;music.volume=1;var p=music.play();if(p&&p.then){p.then(function(){hasStarted=true;setPlaying();removeListeners()}).catch(function(){})}}function onInteraction(e){if(btn.contains(e.target)&&!hasStarted){tryPlay();e.stopPropagation();e.preventDefault();return}if(!hasStarted&&!isFinished){tryPlay()}}var events=["click","touchstart","keydown","mousedown","pointerdown"];function removeListeners(){events.forEach(function(evt){document.removeEventListener(evt,onInteraction,true)})}events.forEach(function(evt){document.addEventListener(evt,onInteraction,true)});music.addEventListener("ended",function(){isFinished=true;setPaused()});btn.addEventListener("click",function(e){e.stopPropagation();e.preventDefault();if(!hasStarted)return;if(isFinished){music.currentTime=0;isFinished=false}if(music.paused){music.play().then(function(){setPlaying()}).catch(function(err){})}else{music.pause();setPaused()}});setTimeout(function(){tryPlay()},300)})();